    "New: Events. Switch it on under Settings → Apps. Put events up, see who’s coming and write to them all; people sign up with one tap and are reminded 3 days and 1 day before – in Messages, and by email if they like.": "Ntho e ntjha: Diketsahalo. E bulele tlasa Disetting → Diapo. Kenya diketsahalo, bona ba tlang mme o ba ngolle bohle; batho ba ingodisa ka ho tobetsa hang mme ba hopotswa matsatsi a 3 le letsatsi le le 1 pele – Melaetsheng, le ka imeile ha ba batla.",
    "In Did you know? and What’s new, the names of buttons and menu items now look like little buttons, so it is easy to see what to tap.": "Ho Na o ne o tseba? le Tse ntjha, mabitso a dikonopo le a dintho tsa menu jwale a shebahala jwaloka dikonopo tse nyane, hore ho be bonolo ho bona seo o lokelang ho se tobetsa.",
    "Events are here: see what’s coming up, tap I’ll be there, and we’ll remind you 3 days and 1 day before.": "Diketsahalo di fihlile: bona se tlang, tobetsa Ke tla ba teng, mme re tla o hopotsa matsatsi a 3 le letsatsi le le 1 pele.",
    "Signed up for an event? Open it and tap Add to my calendar – your phone reminds you too.": "O ingodiseditse ketsahalo? E bule mme o tobetse Kenya almanakeng ya ka – fono ya hao le yona e tla o hopotsa.",
