    "For people who put their name down on a sheet or told you in person. It is in their name, so they see it under Events and get the reminders.": "Bakeng sa batho ba ngotseng mabitso a bona pampiring kapa ba o boleletseng ka molomo. E ka lebitso la bona, kahoo ba e bona tlasa Diketsahalo mme ba fumana dikgopotso.",
    "{name} is already on the list.": "{name} o se a le lenaneng.",
    "Choose someone else": "Kgetha motho e mong",
    "Rosters → Teams: the Administrator, the Rector and the assistant ministers can now write a position’s tooltip, and a new position is added in one box. On a phone, tap the small i beside a position to read its tooltip.": "Rosters → Teams: Motsamaisi, Rector le baruti ba thusang jwale ba ka ngola tooltip ea boemo, 'me boemo bo bocha bo kenngoa lebokosong le le leng. Ho mohala, tobetsa i e nyenyane haufi le boemo ho bala tooltip ea bona.",
    "Easier to read: on your own page your details now come first and your groups last, headings are a little bigger, and the main buttons are a softer orange on every page.": "Ho bonolo ho bala: leqepheng la hao, dintlha tsa hao di tla pele mme dihlopha tsa hao di tle qetellong, dihlooho di kgolwanyane, mme dikonopo tse ka sehloohong di na le orange e bonolo leqepheng ka leng.",
    "Archives look much friendlier: each folder is a coloured tile, documents show what kind of file they are with Preview and Download beside them, you always see where you are, and the newest documents are on the first page.": "Disebelisoa tsa polokelo li shebahala hantle haholo: foldara e 'ngoe le e 'ngoe ke thaele e mebala, litokomane li bontša mofuta oa faele ka Sheba pele le Jarolla ka thoko, kamehla u bona moo u leng teng, 'me litokomane tse ncha li leqepheng la pele.",
    "Rosters → Teams: a position that was added by mistake, or isn’t used any more, can now be deleted (⋯ beside it). Each position’s names fold away until you tap them, and its tooltip is set from the same ⋯ menu.": "Rosters → Teams: boemo bo kentsweng ka phoso, kapa bo sa sebediswang, jwale bo ka hlakolwa (⋯ haufi le bona). Mabitso a boemo ka bong a ipata ho fihlela o a tobetsa, mme tooltip ea bona e behoa ho menu eo ea ⋯.",
    "Adding names from a sheet to an event: each person now has their own guests counter (filled in from “+2” on the sheet). Choose a photo also opens Google Photos on Android.": "Ho kenya mabitso a tswang leqepheng ketsahalong: motho ka mong jwale o na le palo ya hae ya baeti (e tlatswa ho tswa ho “+2” leqepheng). Kgetha foto e bula le Google Photos ho Android.",
    "Say a name instead of typing it: tap the microphone in People’s search, or in any box where you look for someone. Names that sound like what you said come up too – tap the right one.": "Bua lebitso ho ena le ho le ngola: tobetsa maekrofounu patlong ya Batho, kapa lebokoseng lefe kapa lefe moo o batlang motho. Mabitso a utlwahalang jwalo ka seo o se buileng a hlaha le ona – tobetsa le nepahetseng.",
    "Events: a whole paper sign-up sheet at once – open the event, tap From a sheet and take a photo. Church & Trellis reads the names and finds them in People; you check each one. Pastors and Administrators can register someone who isn’t in People yet.": "Diketsahalo: leqephe lohle la ngodiso ka nako e le nngwe – bula ketsahalo, tobetsa Ho tswa leqepheng mme o nke foto. Church & Trellis e bala mabitso mme e a fumana ho Batho; wena o hlahloba e nngwe le e nngwe. Baruti le Batsamaisi ba ka ngodisa motho ya so keng a ba ho Batho.",
    "Visitor cards: People → From a photo reads the names (and any phone numbers and email addresses) and adds the new people as Attenders, after you check each one.": "Dikarete tsa baeti: Batho → Ho tswa fotong e bala mabitso (le dinomoro tsa mohala le diaterese tsa imeile) mme e kenya batho ba batjha e le Bahlahlobi, ka mora hore o hlahlobe e mong le e mong.",
    "Looking for someone? Tap the microphone and say their name – even if it’s heard a little wrong, names that sound like it come up.": "O batla motho? Tobetsa maekrofounu mme o bue lebitso la hae – le ha le ka utlwahala hanyane ka phoso, mabitso a utlwahalang jwalo ka lona a a hlaha.",
