    "Pastors always see and edit everyone’s details, households, children and pastoral notes. Tick what else they may do – up to everything an Administrator does. Medical notes stay with Children’s ministry.": "Baruti kamehla ba bona le ho fetola dintlha tsa bohle, malapa, bana le dintlha tsa boruti. Tshwaya seo ba ka se etsang hape – ho fihlela ho tsohle tseo Motsamaisi a di etsang. Dintlha tsa bongaka di dula le Tshebeletso ya bana.",
