    "Choose…": "Kgetha…",
    "Shaded boxes must be filled in.": "Mabokose a nang le moriti a tlameha ho tlatswa.",
    "Click again to confirm": "Tobetsa hape ho netefatsa",
    "Click again to delete": "Tobetsa hape ho hlakola",
    "Click again to cancel": "Tobetsa hape ho emisa",
    "Demo with made-up people. Changes stay in this browser.": "Pontsho e nang le batho ba iqapetsweng. Diphetoho di dula sebading sena.",
    "Reset demo": "Qala pontsho bocha",
    "Switch person": "Fetola motho",
    "Who is using Church & Trellis?": "Ke mang ya sebedisang Church & Trellis?",
    "{email} is shared by more than one person. Choose who you are – you can switch at any time.": "{email} e sebediswa ke batho ba fetang a le mong. Kgetha hore o mang – o ka fetola neng kapa neng.",
    "Good morning": "Dumela (hoseng)",
    "Good afternoon": "Dumela (motsheare)",
    "Good evening": "Dumela (mantsiboya)",
    "To do": "Tse lokelang ho etswa",
    "Nothing needs you right now.": "Ha ho letho le o hlokang hona jwale.",
    "Apps": "Dikarolo",
    "Administrator": "Motsamaisi",
    "Pastor": "Moruti",
    "Roster coordinator": "Mohlophisi wa manane",
    "Children’s ministry": "Tshebeletso ya bana",
    "Member": "Setho",
    "Basic access": "Phihlello ya motheo",
    "Directory, households and consent": "Bukana, malapa le tumello",
    "Church directory": "Bukana ya kereke",
    "Who serves when – families kept together": "Ke mang ya sebeletsang neng – malapa a dula mmoho",
    "Staff leave – Leave Manager built in": "Phomolo ya basebetsi – Leave Manager e kenyeleditswe",
    "Sign in": "Kena",
    "Loading…": "E a kenya…",
    "Signing you in…": "Re a o kenya…",
    "Getting the latest church records…": "Ho nka direkoto tsa morao-rao tsa kereke…",
    "Church & Trellis is loading your church’s information. The first time, or on a slow connection, this can take a minute. Please wait – nothing is wrong, the app has not crashed.": "Church & Trellis e loaisa tlhahisoleseling ea kereke ea hao. Ka nako ea pele, kapa ka khokahano e liehang, sena se ka nka metsotso e meng. Ka kopo emela – ha ho letho le fosahetseng, lenaneo ha le senyehile.",
    "This is taking longer than usual. Check your internet connection. If nothing changes, tap Try again.": "Ho nka nako e telele ho feta ha ho tloaelehile. Hlahloba khokahano ea hao ea marang-rang. Haeba ho se letho le fetohang, tobetsa Leka hape.",
    "Something went wrong": "Ho na le se sa tsamaeng hantle",
    "Try again": "Leka hape",
    "Back to the top": "Kgutlela hodimo",
    "Go to the bottom": "Eya tlase",
    "Appearance": "Ponahalo",
    "Light": "Kganya",
    "Dark": "Lefifi",
    "Automatic": "Ka boiketsetso",
    "Same as this device": "Ho tshwana le sesebediswa sena",
    "Or pick any colour": "Kapa kgetha mmala ofe kapa ofe",
    "Save the church’s colour": "Boloka mmala wa kereke",
    "Page pictures": "Litšoantšo tsa maqephe",
    "A picture at the top of every page, in the colours of that part of the app. Everyone sees the choice the church makes here.": "Setšoantšo hodima leqephe le leng le le leng, ka mebala ea karolo eo ea app. Mang kapa mang o bona se khethiloeng ke kereke mona.",
    "Warm line art": "Litšoantšo tsa mela tse mofuthu",
    "Soft watercolour": "Watercolour e bonolo",
    "Plain (original)": "E tloaelehileng (ea pele)",
    "New: Me → Themes. Everyone can now choose their own colour and page pictures (soft watercolour, warm line art or plain) – only you see them, on this device – and go back to the church’s theme at any time.": "Ntjha: Nna → Dithime. Mang kapa mang jwale a ka ikgethela mmala wa hae le ditshwantsho tsa maqephe (watercolour e bonolo, line art e futhumetseng kapa e sa kgabisoang) – ke wena feela ya di bonang, sesebelisweng sena – mme o ka khutlela theme ea kereke neng kapa neng.",
    "Every page now has a soft watercolour picture at the top. Administrators and the Rector can choose warm line art instead, or go back to plain, under Settings → Themes → Page pictures.": "Leqephe le leng le le leng ke hona le na le setšoantšo se bonolo sa watercolour hodimo. Batsamaisi le Rector ba ka khutlela ho se tloaelehileng tlasa Litlhophiso → Dithime → Litšoantšo tsa maqephe.",
    "Happy birthday, {name}!": "Letsatsi la tswalo le monate, {name}!",
    "The church is thankful for you. May God bless you richly in the year ahead.": "Kereke e leboha ka wena. Modimo a ke a u hlohonolofatse haholo selemong se tlang.",
    "Happy wedding anniversary!": "Sehopotso se monate sa lenyalo!",
    "Celebrating your marriage today. May God keep blessing it.": "Re keteka lenyalo la hao kajeno. Modimo a tswelepele ho le hlohonolofatsa.",
    "Birthday today": "Letsatsi la tswalo kajeno",
    "Tomorrow": "Hosane",
    "Birthdays this week": "Matsatsi a tswalo bekeng ena",
    "May be a hard day": "E ka ba letsatsi le thata",
    "Only Pastors see this. A call or a visit may mean a lot.": "Ke Baruti feela ba bonang sena. Mohala kapa ketelo e ka bolela haholo.",
    "The anniversary of {name}’s death": "Sehopotso sa lefu la {name}",
    "Their wedding anniversary, since {name} died": "Sehopotso sa bona sa lenyalo, ho tloha ha {name} a hlokahala",
    "Birthdays and anniversaries": "Matsatsi a tswalo le dihopotso",
    "Celebrate my birthday and anniversary": "Keteka letsatsi la ka la tswalo le sehopotso",
    "On your day you get a card here and on Home, and people who can see the church directory see 🎂 or 💍 beside your name – the day only, never the year.": "Ka letsatsi la hao o fumana karete mona le ho Hae, mme batho ba ka bonang lenane la kereke ba bona 🎂 kapa 💍 haufi le lebitso la hao – letsatsi feela, eseng selemo.",
    "Nobody sees 🎂 or 💍 beside your name, and your birthday isn’t in the church directory.": "Ha ho motho ya bonang 🎂 kapa 💍 haufi le lebitso la hao, mme letsatsi la hao la tswalo ha le lenaneng la kereke.",
    "Church Partners now see 🎂 or 💍 beside someone’s name in the church directory on their birthday or wedding anniversary (the day only). Don’t want yours shown? Turn it off on Me → My details.": "Balekane ba Kereke jwale ba bona 🎂 kapa 💍 haufi le lebitso la motho lenaneng la kereke ka letsatsi la hae la tswalo kapa la lenyalo (letsatsi feela). Ha o batle ya hao e bontshwe? E tima ho Nna → Dintlha tsa ka.",
    "Pastors, carers and Midweek Group leaders now see Birthdays this week on Home. Pastors also see who may have a hard day, on the anniversary of a husband’s or wife’s death.": "Baruti, bahlokomedi le baetapele ba Dihlopha tsa Bohareng ba Beke jwale ba bona Matsatsi a tswalo bekeng ena ho Hae. Baruti ba bona hape ba ka bang le letsatsi le thata, ka sehopotso sa lefu la monna kapa mosadi.",
    "Wedding anniversary today": "Sehopotso sa lenyalo kajeno",
    "When you change someone’s home address, Church & Trellis now offers the same address to their husband or wife. People also lists married couples whose addresses don’t match, so they can be put right.": "Ha o fetola aterese ya hae ya motho, Church & Trellis jwale e fana ka aterese e tshwanang ho monna kapa mosadi wa hae. Batho le bona ba bontsha banyalani ba nyetsaneng bao diaterese tsa bona di sa tshwaneng, e le hore di lokiswe.",
    "Birthdays and wedding anniversaries now get a little celebration: on your own day you see a card on Home and Me, and 🎂 or 💍 appears beside a name wherever the church already shows that date.": "Matsatsi a tswalo le dihopotso tsa lenyalo jwale a ketekwa hanyane: ka letsatsi la hao o bona karete ho Hae le ho Nna, mme 🎂 kapa 💍 e hlaha haufi le lebitso moo kereke e se e bontsha letsatsi leo.",
    "Buttons now press down a little when you tap them.": "Dikonopo jwale di hatellwa hanyane ha o di ama.",
    "Orange": "Lamunu",
    "Blue": "Botala ba lehodimo",
    "Green": "Botala",
    "Purple": "Pherese",
    "Burgundy": "Bofubedu bo lefifi",
    "Teal": "Botala ba leoatle",
    "Gold": "Kgauta",
