    "Colours": "Mebala",
    "The church’s colour for buttons, links, the turning cross and the menu – everyone sees it.": "Mmala wa kereke wa dikonopo, dihokelo, sefapano se potolohang le menu – bohle ba a o bona.",
    "Your own colour": "Mmala wa hao",
    "Writing on buttons will be dark, so it stays easy to read.": "Mongolo dikonopong o tla ba lefifi, hore o balehe habonolo.",
    "Check your email": "Sheba imeile ya hao",
    "We sent a sign-in link to {email}. Open it on this device to sign in. It may take a minute, and could land in your spam folder.": "Re rometse lehokela la ho kena ho {email}. Le bule sesebedisweng sena ho kena. Ho ka nka motsotso, mme le ka kena foldareng ya spam.",
    "Use a different way": "Sebedisa tsela e nngwe",
    "Confirm your email": "Netefatsa imeile ya hao",
    "For your safety, type the email address you asked the sign-in link for.": "Bakeng sa polokeho ya hao, ngola aterese ya imeile eo o kopileng lehokela la ho kena ho yona.",
    "unknown": "ha e tsejwe",
    "Unknown": "Ha e tsejwe",
    "Type “{word}” if not known": "Ngola “{word}” haeba ho sa tsejwe",
    "Please fill in the email address, or type “{word}”.": "Ka kopo tlatsa aterese ya imeile, kapa o ngole “{word}”.",
    "Please fill in the mobile number, or type “{word}”.": "Ka kopo tlatsa nomoro ya selefouno, kapa o ngole “{word}”.",
    "That mobile number doesn’t look right.": "Nomoro eo ya selefouno ha e bonahale e nepahetse.",
    "Email": "Imeile",
    "No access yet": "Ha o eso fumane tumello",
    "Your email address ({email}) hasn’t been verified. Sign in with Google or an email link instead.": "Aterese ya hao ya imeile ({email}) ha e so netefatswe. Kena ka Google kapa ka lehokela la imeile.",
    "Church & Trellis hasn’t been set up yet. Please try again later.": "Church & Trellis ha e eso lokiswe. Ka kopo leka hape hamorao.",
    "You have access, but your person record is missing. Please ask the church office.": "O na le tumello, empa rekoto ya hao ha e yo. Ka kopo botsa ofisi ya kereke.",
    "You are signed in as {email}, but this email address hasn’t been given access to Church & Trellis. Ask the church office to add it, or sign out and use another account.": "O kene jwalo ka {email}, empa aterese ena ya imeile ha e a fuwa tumello ho Church & Trellis. Kopa ofisi ya kereke hore e e kenye, kapa o tswe o sebedise akhaonte e nngwe.",
    "For church staff, leaders and members who have been given access.": "Bakeng sa basebetsi, baetapele le ditho tsa kereke ba fuweng tumello.",
    "Sign in with Google": "Kena ka Google",
    "or get a sign-in link by email": "kapa o fumane lehokela la ho kena ka imeile",
    "Email me a link": "Nthomelle lehokela",
    "Want to look around first?": "O batla ho qala ka ho sheba?",
    "Try the demo with made-up people": "Leka pontsho e nang le batho ba iqapetsweng",
    "Please type your email address.": "Ka kopo ngola aterese ya hao ya imeile.",
    "We couldn’t send the link. Check the address and try again.": "Re hlolehile ho romela lehokela. Sheba aterese mme o leke hape.",
    "Signing in by email link isn’t switched on yet. Please use Google, or ask the church office.": "Ho kena ka lehokela la imeile ha ho so bulwe. Ka kopo sebedisa Google, kapa o botse ofisi ya kereke.",
    "Signing in by email link isn’t allowed from this web address yet. Please use Google, or ask the church office.": "Ho kena ka lehokela la imeile ha ho so dumellwe ho tswa atereseng ena ya webo. Ka kopo sebedisa Google, kapa o botse ofisi ya kereke.",
    "Google sign-in didn’t work ({code}). Try again, or use the email link.": "Ho kena ka Google ha ho a sebetsa ({code}). Leka hape, kapa o sebedise lehokela la imeile.",
    "This is a demo with made-up people. Choose who to be: each role sees different things.": "Ena ke pontsho e nang le batho ba iqapetsweng. Kgetha hore o be mang: karolo ka nngwe e bona dintho tse fapaneng.",
    "Or anyone else": "Kapa motho e mong",
    "When live: sign in with Google or an email link.": "Ha e sebetsa: kena ka Google kapa ka lehokela la imeile.",
