    "That is fine while Church & Trellis is used only by this church. Before other churches use it, ask Claude to translate them.": "Ho lokile ha Church & Trellis e sebediswa ke kereke ena feela. Pele dikereke tse ding di e sebedisa, kopa Claude ho di fetolela.",
    "Remind me in 3 days": "Nkgopotse ka mora matsatsi a 3",
    "{n} text is still in English in the {count} extra languages (German, French, Portuguese and the others). English, Afrikaans, isiZulu, isiXhosa and Sesotho are complete.": "Sengolwa se {n} se ntse se le ka Senyesemane dipuong tse {count} tse eketsehileng (Sejeremane, Sefora, Sepotokisi le tse ding). Senyesemane, Seafrikanse, isiZulu, isiXhosa le Sesotho di phethehile.",
    "{n} texts are still in English in the {count} extra languages (German, French, Portuguese and the others). English, Afrikaans, isiZulu, isiXhosa and Sesotho are complete.": "Dingolwa tse {n} di ntse di le ka Senyesemane dipuong tse {count} tse eketsehileng (Sejeremane, Sefora, Sepotokisi le tse ding). Senyesemane, Seafrikanse, isiZulu, isiXhosa le Sesotho di phethehile.",
    "Archives": "Polokelo ya ditokomane",
    "Restricted View — Access restricted to Council members and Administrators only.": "Pono e thibetsweng — e bulehetse ditho tsa Lekgotla le Batsamaisi feela.",
    "Where are documents stored?": "Ditokomane di bolokwa kae?",
    "Display on Membership Application Form": "Bontsha foromong ya kopo ya botho",
    "Everyone who can sign in can read this document.": "Bohle ba ka kenang ba ka bala tokomane ena.",
    "Loading preview…": "Ho bula ponelopele…",
    "The preview did not load. Check the document’s sharing settings, or open it in Google Docs.": "Ponelopele ha e a buleha. Hlahloba ditlhophiso tsa ho arolelana tsa tokomane, kapa o e bule ho Google Docs.",
    "If you cannot see the document, check its sharing settings or open it in Google Docs.": "Haeba o sa bone tokomane, hlahloba ditlhophiso tsa yona tsa ho arolelana kapa o e bule ho Google Docs.",
    "Open in Google Docs": "Bula ho Google Docs",
    "Physical documents: [add shelf/cabinet and filing details]. Uploaded files are stored in the church’s Firestore database in South Africa. Linked files stay in their cloud folder: [add provider and folder details]. Replace these placeholders with the church’s actual locations.": "Ditokomane tsa pampiri: [kenya dintlha tsa shelofo/khabinete le tsa ho boloka]. Difaele tse kentsweng di bolokwa polokelong ya Firestore ya kereke Afrika Borwa. Difaele tse hokahantsweng di dula foldareng ya tsona ya inthanete: [kenya dintlha tsa mofani le foldara]. Nkela dibaka tsena sebaka ka dibaka tsa nnete tsa kereke.",
    "Only an Administrator can change a document displayed on the membership form.": "Ke Motsamaisi feela ya ka fetolang tokomane e bontshwang foromong ya botho.",
    "Only an Administrator can remove a document displayed on the membership form.": "Ke Motsamaisi feela ya ka tlosang tokomane e bontshwang foromong ya botho.",
    "Couldn’t remove the document from the membership form. Please try again.": "Ha re a kgona ho tlosa tokomane foromong ya botho. Ka kopo leka hape.",
    "This group follows the staff details on your profile.": "Sehlopha sena se latela dintlha tsa basebetsi profaeleng ya hao.",
    "Group settings": "Ditlhophiso tsa sehlopha",
