    "Review possible matches. Standardizing changes catalogue details only; copies and loan records stay separate.": "Hlahloba tse ka nnang tsa tshwana. Ho di tsamaisa ka mokgwa o le mong ho fetola dintlha tsa lenane feela; dikopi le direkoto tsa kadimo di dula di arohane.",
    "No possible duplicates were found.": "Ha ho tse ka nnang tsa phetwa tse fumanweng.",
