    "Pending Verifications": "Tse emetseng ho netefatswa",
    "Return every copy before marking this item for repair.": "Kgutlisa kopi e nngwe le e nngwe pele o tshwaya ntho ena hore e lokiswe.",
    "Catalogue details standardized": "Dintlha tsa lenane di tsamaiswa ka mokgwa o le mong",
    "Checkout request sent. A librarian will verify it.": "Kopo ya kadimo e rometswe. Mohlokomedi wa laeborari o tla e netefatsa.",
    "Couldn’t send the checkout request. The item may no longer be available; please try again.": "Ha re a kgona ho romela kopo ya kadimo. Mohlomong ntho ena ha e sa fumaneha; ka kopo leka hape.",
    "Checkout approved": "Kadimo e amohetswe",
