    "Marked as being repaired": "E tshwailwe e le e lokiswang",
    "Whenever necessary (could be every week)": "Neng kapa neng ha ho hlokahala (e ka ba beke le beke)",
    "Only now and then in emergencies": "Ka nako tse ding feela maemong a tshohanyetso",
    "Keep your current preference: {how}": "Boloka kgetho ya hao ya hajwale: {how}",
