    "Please update the Church & Trellis app to download files, or use a browser.": "Ka kopo ntjhafatsa app ya Church & Trellis ho jarolla difaele, kapa o sebedise sebadi.",
    "Add a photo of yourself": "Kenya setshwantsho sa hao",
    "So people at church can put a face to your name. Only people who may see your details see it.": "Hore batho ba kereke ba kgone ho tseba sefahleho sa hao. Ke batho ba dumelletsweng ho bona dintlha tsa hao feela ba se bonang.",
    "Take or choose a photo": "Nka kapa o kgethe setshwantsho",
    "Church & Trellis on your iPhone": "Church & Trellis ho iPhone ya hao",
    "Tap the Share button (the square with an arrow), then “Add to Home Screen”. Church & Trellis then opens like an app, full screen, with its own icon.": "Tobetsa konopo ya Share (sekwere se nang le motsu), ebe “Add to Home Screen”. Church & Trellis e tla bula jwalo ka app, skrineng kaofela, ka letshwao la yona.",
