    "A two minute WhatsApp message from Richard Sturdee, focussing on the person and work of our Lord Jesus Christ.": "Molaetsa wa WhatsApp wa metsotso e mmedi o tswang ho Richard Sturdee, o shebaneng le botho le mosebetsi wa Morena wa rona Jesu Kreste.",
