    "Version {v}": "Phetolelo ya {v}",
    "Everyone sees the names of people who agreed to share their contact details. Tick what else each role may see. Administrators and Pastors always see everything.": "Bohle ba bona mabitso a batho ba dumetseng ho arolelana dintlha tsa bona tsa ho ikopanya. Tshwaya seo karolo ka nngwe e ka se bonang hape. Batsamaisi le Baruti ba lula ba bona tsohle.",
    "People with Basic access see these as pictures: they can read them, but can’t tap or copy them. Care Group leaders see more of their own group (Care Groups).": "Batho ba nang le phihlello ya motheo ba di bona e le ditshwantsho: ba ka di bala, empa ba ke ke ba di tobetsa kapa ba di kopitsa. Baetapele ba dihlopha tsa tlhokomelo ba bona tse ngata tsa sehlopha sa bona (Dihlopha tsa tlhokomelo).",
