    "This language was translated by computer and is still being checked. If something reads oddly, please tell the church office.": "Puo ena e fetoletswe ke khomphutha mme e ntse e hlahlojwa. Haeba ho na le se balehang hampe, ka kopo bolella ofisi ya kereke.",
