    "Photo, phone, email, address and birthday shared with my Care Group.": "Setshwantsho, mohala, imeile, aterese le letsatsi la tswalo di arolelanwa le sehlopha sa ka sa tlhokomelo.",
    "My Care Group": "Sehlopha sa ka sa tlhokomelo",
