    "Empty": "E se na letho",
    "Latest documents": "Ditokomane tsa morao tjena",
    "Nothing in this folder yet.": "Ha ho so be le letho foldareng ena.",
    "Show a summary before saving": "Bontsha kakaretso pele ho boloka",
    "New folder inside this one": "Foldara e ntjha ka hara ena",
    "New folder": "Foldara e ntjha",
    "Change this folder": "Fetola foldara ena",
    "It will be filed in: {place}": "E tla bolokwa ho: {place}",
    "Use {date}": "Sebedisa {date}",
    "The date, {date}, hasn’t come yet. Is that right?": "Letsatsi, {date}, ha le so fihle. Na ho nepahetse?",
    "The year {year} looks like a typing slip.": "Selemo sa {year} se shebahala e le phoso ya ho ngola.",
    "The title or file name speaks of {when}, but the date is {date}.": "Sehlooho kapa lebitso la faele le bua ka {when}, empa letsatsi ke {date}.",
    "The other documents for {month} are dated {date}. Is this for the same meeting?": "Ditokomane tse ding tsa {month} di na le letsatsi la {date}. Na ena ke ya kopano e le nngwe?",
    "There is already a document called “{title}” in {place}.": "Ho se ho ena le tokomane e bitswang “{title}” ho {place}.",
    "Move “{title}” from {from} to {to}.": "Tlosa “{title}” ho {from} o e ise ho {to}.",
    "Keep “{title}” in {place}.": "Boloka “{title}” ho {place}.",
    "File “{title}” in {place}.": "Boloka “{title}” ho {place}.",
    "It is the first document for {month}, so that folder will appear by itself.": "Ke tokomane ya pele ya {month}, ka hona foldara eo e tla hlaha ka bo yona.",
    "Who can see it: {who}.": "Ba ka e bonang: {who}.",
    "{name} can see it too.": "{name} le yena a ka e bona.",
    "Keep {file} ({size}) in Church & Trellis.": "Boloka {file} ({size}) ho Church & Trellis.",
    "Keep a link to where it is kept.": "Boloka sehokelo sa moo e bolokilweng teng.",
    "Show it on the Membership Application Form, where everyone who signs in can read it.": "E bontshe Foromong ya Kopo ya Botho, moo bohle ba kenang ba ka e balang.",
    "You wouldn’t be able to see this record yourself. Under “Who can see it”, choose a group you belong to.": "O ne o ke ke wa bona rekoto ena ka bowena. Tlasa “Ke mang ya ka e bonang”, kgetha sehlopha seo o leng ho sona.",
    "Please check the date": "Ka kopo hlahloba letsatsi",
    "Here’s what Church & Trellis is about to do": "Sena ke seo Church & Trellis e tlang ho se etsa",
    "Don’t show this summary again": "O se ke wa bontsha kakaretso ena hape",
    "Save straight away from now on. Church & Trellis will still ask when a date looks wrong. You can switch it back on under More.": "Boloka hanghang ho tloha jwale. Church & Trellis e tla nne e botse ha letsatsi le shebahala le fosahetse. O ka e bulela hape tlasa Tse ding.",
    "Go back and change it": "Kgutlela morao o e fetole",
    "Save anyway": "Boloka leha ho le jwalo",
    "Folders keep the church’s records in order, like folders on a computer.": "Difoldara di boloka direkoto tsa kereke di hlophisehile, jwalo ka difoldara khomputareng.",
    "Inside": "Ka hare",
    "At the top of the Archives": "Ka hodimo ho Polokelo",
