    "Added by mistake?": "E kenyelelitsoe ka phoso?",
    "Delete it completely, as if it had never been added.": "E hlakole ka ho feletseng, joaloka eka e ne e sa kenngoa.",
    "Take out": "Ntša",
    "A spreadsheet saved as CSV, with a heading on each column: Title (needed), and any of Author, Type, Category, Copies, Shelf, ISBN, Date acquired, How acquired, Donated by, Note.": "Spreadsheet e bolokiloeng e le CSV, ka hlooho kholomong e 'ngoe le e 'ngoe: Title (e hlokahalang), le e 'ngoe ea Author, Type, Category, Copies, Shelf, ISBN, Date acquired, How acquired, Donated by, Note.",
    "Church & Trellis couldn’t find a Title column. The first row must hold the headings, one of them Title.": "Church & Trellis ha e fumane kholomo ea Title. Mola oa pele o tlameha ho ba le lihlooho, e 'ngoe ea tsona e be Title.",
