    "Midweek Group": "Sehlopha sa bophelo",
    "Group leader": "Moetapele wa sehlopha",
    "My Midweek Groups": "Dihlopha tsa ka tsa bophelo",
    "Add a Midweek Group": "Kenya sehlopha sa bophelo",
    "e.g. Tuesday Bible study": "mohl. Thuto ya Bibele ya Labobedi",
    "No Midweek Groups yet.": "Ha ho dihlopha tsa bophelo hajoale.",
    "Midweek Group added": "Sehlopha sa bophelo se kentswe",
    "Midweek Group deleted": "Sehlopha sa bophelo se hlakotswe",
    "You’re not in a Midweek Group yet. Ask the church office or a group leader to add you.": "Ha o eso be sehlopheng sa bophelo. Kopa ofisi ya kereke kapa moetapele wa sehlopha hore a o kenye.",
    "People in your Midweek Group see your details only if you are in the church directory (under Consent).": "Batho ba sehlopheng sa hao sa bophelo ba bona dintlha tsa hao feela ha o le Bukaneng ya kereke (tlasa Tumello).",
    "Bible studies, life groups, Connect Groups and other Midweek Groups. A person can be in more than one. Members see each other’s photo, phone, email, address and birthday if they are in the church directory. Group leaders can name their group and add and remove members.": "Dithuto tsa Bibele, dihlopha tsa bophelo le dikopano tsa bohareng ba beke. Motho a ka ba ho tse fetang se le seng. Ditho di bona setshwantsho, mohala, imeile, aterese le letsatsi la tswalo la ba bang ha ba le Bukaneng ya kereke. Baetapele ba dihlopha ba ka rea sehlopha sa bona lebitso, ba kenya le ho ntsha ditho.",
    "Bible studies, life groups, Connect Groups – their leaders name them": "Dithuto tsa Bibele, dihlopha tsa bophelo le dihlopha tsa bohareng ba beke – baetapele ba tsona ba di rea mabitso",
    "A Bible Study, Life Group or Connect Group (etc) that meets during the week for teaching and fellowship": "Thuto ya Bibele, sehlopha sa bophelo kapa Connect Group (jj.) se kopanang hara beke bakeng sa thuto le kopano",
    "Someone who leads a Midweek Group": "Motho ya etellang sehlopha sa bophelo pele",
    "{n} person in a Care Group isn’t in the church directory, so Church Partners don’t see them on the Care Groups page.": "Motho ya {n} sehlopheng sa tlhokomelo ha a lenaneng la kereke, ka hona Balekane ba Kereke ha ba mmone leqepheng la dihlopha.",
    "{n} people in Care Groups aren’t in the church directory, so Church Partners don’t see them on the Care Groups page.": "Batho ba {n} dihlopheng tsa tlhokomelo ha ba lenaneng la kereke, ka hona Balekane ba Kereke ha ba ba bone leqepheng la dihlopha.",
    "Show them": "Ba bontshe",
    "Contact details not asked yet": "Ha ba so botswe ka dintlha tsa kgokahano",
    "“Record that they agreed” records it for Church Partners; for anyone else, record their answer on their profile (Consent).": "“Ngola hore ba dumetse” e ngolla Balekane ba Kereke; ho ba bang, ngola karabo ya bona profaeleng ya bona (Tumello).",
    "Said no to sharing their contact details": "O hanne ho arolelana dintlha tsa kgokahano",
    "They stay hidden unless they change their mind (their profile → Consent).": "Ba dula ba patilwe ntle le haeba ba fetola maikutlo (profaele ya bona → Tumello).",
    "No longer active": "Ha a sa sebetsa",
    "Take them out of their Care Group, or mark them active again.": "Ba ntshe sehlopheng sa bona, kapa o ba tshwaye e le ba sebetsang hape.",
    "Children are never shown to other members.": "Bana ha ba bontshwe ditho tse ding.",
    "In Care Groups, but not in the church directory": "Dihlopheng tsa tlhokomelo, empa ha ba lenaneng la kereke",
    "Their own group: see all its members": "Sehlopha sa bona: bona ditho tsohle",
    "(not just the carers)": "(eseng bahlokomedi feela)",
    "All groups: see who is in each group": "Dihlopha tsohle: bona hore ke mang ya sehlopheng ka seng",
    "(names only, on a Care Groups page)": "(mabitso feela, leqepheng la dihlopha tsa tlhokomelo)",
    "You’re not in a Care Group yet.": "Ha o so be sehlopheng sa tlhokomelo.",
    "All Care Groups": "Dihlopha tsohle tsa tlhokomelo",
    "Find a Care Group or a person": "Fumana sehlopha sa tlhokomelo kapa motho",
    "Type part of a group’s name or a person’s name": "Ngola karolo ya lebitso la sehlopha kapa la motho",
    "No Care Group or person matches what you typed.": "Ha ho sehlopha sa tlhokomelo kapa motho ya tsamaellanang le seo o se ngotseng.",
    "Back to {role}": "Kgutlela ho {role}",
    "Agreed on becoming a Church Partner": "O dumetse ha a eba Molekane wa Kereke",
    "{n} Church Partner has no Contact details answer recorded. If they agreed when they became a Church Partner, record it here.": "Molekane wa Kereke ya {n} ha a na karabo e ngotsweng ka Dintlha tsa kgokahano. Haeba ba dumetse ha ba eba Molekane wa Kereke, e ngole mona.",
    "{n} Church Partners have no Contact details answer recorded. If they agreed when they became Church Partners, record it here.": "Balekane ba Kereke ba {n} ha ba na karabo e ngotsweng ka Dintlha tsa kgokahano. Haeba ba dumetse ha ba eba Balekane ba Kereke, e ngole mona.",
    "Record that they agreed": "Ngola hore ba dumetse",
    "Click again: record it for them": "Tobetsa hape: ba ngolle yona",
    "See everyone in their own Care Group": "Bona bohle ba sehlopheng sa bona sa tlhokomelo",
    "See which Care Group each person in the church directory is in": "Bona hore motho e mong le e mong ya lenaneng la kereke o sehlopheng sefe sa tlhokomelo",
    "Which Care Group each person in the church directory is in, and who the carers are.": "Hore motho e mong le e mong ya lenaneng la kereke o sehlopheng sefe sa tlhokomelo, le hore bahlokomedi ke bomang.",
    "The church shows you your carers here; they can see everyone in the group.": "Kereke e o bontsha bahlokomedi ba hao mona; bona ba bona bohle ba sehlopheng.",
    "See the Care Groups and who is in them": "Bona dihlopha tsa tlhokomelo le hore ke bomang ba leng ho tsona",
    "Who is in which Care Group, and who their carers are. Only Administrators and Pastors can change the groups.": "Ke mang ya leng sehlopheng sefe sa tlhokomelo, le hore bahlokomedi ba sona ke bomang. Ke Batsamaisi le Baruti feela ba ka fetolang dihlopha.",
    "Tick which Care Group(s) they are in (or untick Care Group member).": "Tshwaya hore ba sehlopheng (dihlopheng) sefe sa tlhokomelo (kapa o tlose letshwao ho Setho sa sehlopha sa tlhokomelo).",
    "Only Administrators and Pastors can set up Care Groups.": "Ke Batsamaisi le Baruti feela ba ka thehang dihlopha tsa tlhokomelo.",
    "Small groups that care for one another. A person can be in more than one group. Members see each other’s photo, phone, email, address and birthday – only if they agreed (consent “Care Group”). Carers can add and remove members of their own group.": "Dihlopha tse nyane tse hlokomelanang. Motho a ka ba dihlopheng tse fetang se le seng. Ditho di bona setshwantsho, mohala, imeile, aterese le letsatsi la tswalo la e mong le e mong – feela ha ba dumetse (tumello ya “Sehlopha sa tlhokomelo”). Bahlokomedi ba ka eketsa le ho tlosa ditho tsa sehlopha sa bona.",
    "Add a Care Group": "Eketsa sehlopha sa tlhokomelo",
    "e.g. Hilton Tuesday evening": "mohl. Hilton Labobedi mantsiboya",
    "Rename {name}": "Fetola lebitso la {name}",
    "Rename": "Fetola lebitso",
    "Suggest groups by where people live": "Sisinya dihlopha ho ya ka moo batho ba dulang teng",
    "Areas: {areas}": "Dibaka: {areas}",
    "Areas it covers": "Dibaka tseo e di akgang",
    "e.g. Hilton, Howick North, 3245": "mohlala Hilton, Howick North, 3245",
    "Suburbs, towns or postal codes, separated by commas – used to suggest groups by where people live.": "Metse, ditoropo kapa dikhoutu tsa poso, di arohantswe ka dikhoma – di sebediswa ho sisinya dihlopha ho ya ka moo batho ba dulang teng.",
    "their area": "sebaka sa bona",
