    "Lives in {place}, an area of this group": "O dula {place}, sebaka sa sehlopha sena",
    "Lives in {place}, like others in this group": "O dula {place}, jwalo ka ba bang ba sehlopha sena",
    "No home address": "Ha ho aterese ya lehae",
    "Lives in {place} – which part? Closest groups: {groups}": "O dula {place} – karolong efe? Dihlopha tse haufi: {groups}",
    "No Care Group in {place} yet": "Ha ho eso be le sehlopha sa tlhokomelo {place}",
    "The people they live with are in different groups: {groups}": "Batho bao a dulang le bona ba dihlopheng tse fapaneng: {groups}",
    "Close to more than one group: {groups}": "Haufi le dihlopha tse fetang se le seng: {groups}",
    "Choose a group": "Kgetha sehlopha",
    "Care Group for {name}": "Sehlopha sa tlhokomelo sa {name}",
    "Suggested Care Groups": "Dihlopha tsa tlhokomelo tse sisintsweng",
    "For Church Partners not yet in a Care Group, from their home address (or their household’s). Nothing changes until you confirm: check each one, change the group if needed, then put the ticked people in their groups.": "Bakeng sa ditho tsa kereke tse so keneng sehlopheng sa tlhokomelo, ho ya ka aterese ya bona (kapa ya lelapa la bona). Ha ho letho le fetohang ho fihlela o netefatsa: hlahloba e nngwe le e nngwe, fetola sehlopha ha ho hlokahala, ebe o kenya batho ba tshwailweng dihlopheng tsa bona.",
    "Every Church Partner is already in a Care Group.": "Ditho tsohle tsa kereke di se di le dihlopheng tsa tlhokomelo.",
    "Not clear – choose a group yourself": "Ha ho a hlaka – ikgethele sehlopha",
    "★ marks the groups that are closest.": "★ e bontsha dihlopha tse haufi haholo.",
    "Put the ticked people in their groups": "Kenya batho ba tshwailweng dihlopheng tsa bona",
    "Tick at least one person and choose their group": "Tshwaya bonyane motho a le mong mme o kgethe sehlopha sa hae",
    "{n} person put in a Care Group": "Motho a {n} o kentswe sehlopheng sa tlhokomelo",
    "{n} people put in Care Groups": "Batho ba {n} ba kentswe dihlopheng tsa tlhokomelo",
    "Duplicate {name}": "Kopitsa {name}",
    "Duplicate the group, with all its members": "Kopitsa sehlopha, le ditho tsohle tsa sona",
    "Delete {name}": "Hlakola {name}",
    "Delete the group": "Hlakola sehlopha",
    "details not shared (no consent yet)": "dintlha ha di arolelanwe (ha ho tumello hajwale)",
    "Not a carer": "Hase mohlokomedi",
    "Make carer": "Mo etse mohlokomedi",
    "Take {name} out": "Ntsha {name}",
