    "No one yet.": "Ha ho motho hajwale.",
    "Also in {groups}": "Hape o ho {groups}",
    "Add someone: type part of their name": "Eketsa motho: ngola karolo ya lebitso la hae",
    "No Care Groups yet.": "Ha ho dihlopha tsa tlhokomelo hajwale.",
    "Members’ cards update when their details or consent change.": "Dikarete tsa ditho di ntjhafatswa ha dintlha kapa tumello ya bona e fetoha.",
    "Update everyone’s cards now": "Ntjhafatsa dikarete tsa bohle hona jwale",
    "{n} group": "Sehlopha se {n}",
    "{n} groups": "Dihlopha tse {n}",
    "Give the group a name": "Fa sehlopha lebitso",
    "There is already a group with that name": "Ho se ho na le sehlopha se nang le lebitso leo",
    "Care Group added": "Sehlopha sa tlhokomelo se eketsitswe",
    "{n} person will be in the new group too": "Motho a {n} o tla ba sehlopheng se setjha le yena",
    "{n} people will be in the new group too": "Batho ba {n} ba tla ba sehlopheng se setjha le bona",
    "Name of the new group": "Lebitso la sehlopha se setjha",
    "{name} (copy)": "{name} (kopi)",
    "Keep the same carers": "Boloka bahlokomedi ba tshwanang",
    "Duplicate": "Kopitsa",
    "There is already a group with that name.": "Ho se ho na le sehlopha se nang le lebitso leo.",
    "Give the new group a name.": "Fa sehlopha se setjha lebitso.",
    "Care Group duplicated": "Sehlopha sa tlhokomelo se kopitsitswe",
    "Care Group deleted": "Sehlopha sa tlhokomelo se hlakotswe",
    "Choose someone to add": "Kgetha motho eo o tla mo eketsa",
    "{name} added to the group": "{name} o eketsitswe sehlopheng",
    "Updating cards…": "Ho ntjhafatswa dikarete…",
    "Cards updated": "Dikarete di ntjhafaditswe",
    "Roster": "Lenane",
    "Teams": "Dihlopha tsa mosebetsi",
    "Who is serving at each service. Families and friends who asked to serve together are kept together.": "Hore na ke mang ya sebeletsang tshebeletsong e nngwe le e nngwe. Malapa le metswalle e kopileng ho sebeletsa mmoho e bolokwa mmoho.",
    "Earlier services": "Ditshebeletso tsa pele",
    "Services side by side": "Ditshebeletso pela tse ding",
    "Side by side:": "Pela tse ding:",
    "Show {n} service at a time": "Bontsha tshebeletso e {n} ka nako",
    "Show {n} services at a time": "Bontsha ditshebeletso tse {n} ka nako",
    "<b>{n}</b> service": "Tshebeletso e <b>{n}</b>",
    "<b>{n}</b> services": "Ditshebeletso tse <b>{n}</b>",
    "Fewer services": "Ditshebeletso tse fokolang",
    "More services": "Ditshebeletso tse ngata",
    "Fits your screen": "E lekana skrine sa hao",
    "Fit my screen": "Lekanya le skrine sa ka",
    "1 month": "Kgwedi e 1",
    "1 quarter": "Kotara e 1",
    "Church Hub has a new name: Church & Trellis. Everything works as before, and nothing you have saved has changed.": "Church Hub e na le lebitso le letjha: Church & Trellis. Tsohle di sebetsa jwalo ka pele, mme ha ho letho leo o le bolokileng le fetohileng.",
    "Rosters now open with as many services as fit your screen. Use − and + to see from 1 to 16 side by side, or choose 1 month or 1 quarter and slide across.": "Lenane jwale le bulwa ka ditshebeletso tse ngata kamoo di lekanang skrine sa hao. Sebedisa − le + ho bona ho tloha ho 1 ho isa ho 16 pela tse ding, kapa o kgethe kgwedi e 1 kapa kotara e 1 ebe o sutumetsa ka lehlakoreng.",
    "Rosters: choose how many services to see side by side, from 2 to 8, and the top row (date, time and communion) stays in view as you scroll down.": "Lenane: kgetha hore o batla ho bona ditshebeletso tse kae pela tse ding, ho tloha ho 2 ho isa ho 8, mme mola o ka hodimo (letsatsi, nako le selallo) o dula o bonahala ha o theohela tlase.",
    "Every service is hidden. Tap one above to show it again.": "Ditshebeletso tsohle di patilwe. Tobetsa e nngwe ka hodimo ho e bontsha hape.",
    "Hide the {service} for now": "Pata {service} hajwale",
    "Rosters on a phone: the roster now shows two or three services side by side instead of just one – swipe sideways to see more, or use the arrows either side of the date.": "Manane a tshebeletso ho founu: manane jwale a bontsha ditshebeletso tse pedi kapa tse tharo hammoho ho sebediswa e le nngwe feela – suthisetsa ka lehlakoreng ho bona tse ding, kapa sebedisa metsu ka mahlakoreng a letsatsi.",
    "Rosters: anyone can now print or download the whole roster as a PDF – portrait or landscape, for a month up to a year, with the positions down the side and every Sunday across the top. A Sunday with no service stays as a column and says so. Rosters → My serving → Print or download the roster (planners: More).": "Mang kapa mang jwale a ka hatisa kapa a khoasolla lenane lohle e le PDF – e emeng kapa e robetseng, ho tloha ho kgwedi e le nngwe ho isa selemong, maemo a le ka lehlakoreng le Lisontaha tsohle hodimo. Sontaha se se nang tšebeletso se dula e le kholomo mme se re jwalo. Manane a tshebeletso → Tshebeletso ya ka → Hatisa kapa khoasolla lenane (bahlophisi: Tse ding).",
    "Rosters has a tidier top: Print now has its own button, and the arrows and date for moving between Sundays sit just above the roster.": "Lenane le na le karolo e hodimo e hlophisehileng: Hatisa jwale e na le konopo ya yona, mme metsu le letsatsi la ho tsamaya pakeng tsa Mesontaha di hodimo ho lenane.",
    "Rosters: a position can now need a different number of people at each service – on Rosters → Teams choose the service (8am, 10am or 5pm) and tap − or +. The roster, the gaps and the printed roster follow it.": "Lenane la ditshebeletso: boemo bo ka hloka palo e fapaneng ya batho tshebeletsong e nngwe le e nngwe – ho Rosters → Teams kgetha tshebeletso (8am, 10am kapa 5pm) ebe o tobetsa − kapa +. Lenane, mekoti le lenane le hatisitsweng di a e latela.",
    "Rosters: a service that is cancelled keeps a narrow column on the roster – on screen, on paper and in the PDF – with the note written up its side. Tap ⋯ under its date → Cancel this service…; everyone on it stays on the roster, can be sent a friendly message, and comes back when you put the service back.": "Lenane: tšebeletso e hlakotsweng e boloka kholomo e nyane lenaneng – skrineng, pampiring le ho PDF – le noto e ngotsoeng ka lehlakoreng la yona. Tobetsa ⋯ tlas’a letsatsi la yona → Hlakola tšebeletso ena…; bohle ba ho yona ba lula lenaneng, ba ka fumana molaetsa o mofuthu, mme ba khutla ha o khutlisa tšebeletso.",
    "If a service you were rostered on is cancelled, Me → Serving now says Cancelled (and you may get a friendly message), and the printed roster keeps a narrow column for it.": "Haeba tšebeletso eo o neng o le lenaneng ho yona e hlakoloa, Nna → Tshebeletso jwale e re E hlakotswe (mme o ka fumana molaetsa o mofuthu), mme lenane le hatisitsoeng le boloka kholomo e nyane ho yona.",
    "Service cancelled? Don’t delete it: tap ⋯ under its date on Rosters and choose Cancel this service… – the roster keeps a narrow column for it, and you can tell everyone on it kindly.": "Tšebeletso e hlakotswe? Se e hlakole ka ho feletseng: tobetsa ⋯ tlas’a letsatsi la yona ho Lenane mme o kgethe Hlakola tšebeletso ena… – lenane le boloka kholomo e nyane, mme o ka tsebisa bohle ba ho yona ka mofuthu.",
    "Print the roster a term at a time on A4: each service gets its own page, showing only the positions with names on them. Rosters → More → Print the roster (Pastors: on My serving). Choose “Save as PDF” to make a PDF.": "Hatisa lenane kotara ka kotara ho A4: tshebeletso ka nngwe e fumana leqephe la yona, le bontshang feela maemo a nang le mabitso. Lenane → Tse ding → Hatisa lenane (Baruti: ho Tshebeletso ya ka). Kgetha “Save as PDF” ho etsa PDF.",
    "Also print positions that are still empty, to fill in by hand": "Hatisa le maemo a ntseng a se na letho, ho a tlatsa ka letsoho",
    "Otherwise only positions with names on them are printed.": "Ho seng jwalo ho hatiswa feela maemo a nang le mabitso.",
    "Print or download the roster": "Hatisa kapa khoasolla lenane",
    "On A4, as a PDF to download or on paper. The dates run across the top and the positions down the side.": "Ho A4, e le PDF ho e khoasolla kapa pampiring. Matsatsi a ea hodimo mme maemo a ea ka lehlakoreng.",
    "How long": "Nako e kae",
