    "e.g. Public holiday": "mohlala: Letsatsi la phomolo la sechaba",
    "Everyone on the roster stays on it, out of sight, so you can put the service back at any time.": "Bohle ba lenaneng ba lula ho lona, empa ha ba bonahale, kahoo o ka khutlisa tšebeletso neng kapa neng.",
