    "{n} services put back": "Litšebeletso tse {n} li khutlisitswe",
    "{n} person told": "Motho a le {n} o tsebisitswe",
    "{n} people told": "Batho ba {n} ba tsebisitswe",
    "{n} can’t open Church & Trellis yet – tell them yourself": "{n} ha ba khone ho bula Church & Trellis hajoale – ba tsebise ka bowena",
    "Your {service} on {date} is cancelled": "{service} ya hao ka {date} e hlakotswe",
    "Good news: the {service} on {date} is back on": "Litaba tse molemo: {service} ka {date} e khutlile",
    "Hi {name}, just a friendly note that the {service} on {date} won’t be taking place{why}. You’re off the hook that day, and we’re so grateful for the way you serve. If it’s put back on, we’ll let you know. See you soon! 🙏": "Dumela {name}, ke molaetsa o mofuthu feela: {service} ka {date} e ke ke ya ba teng{why}. Ha o hloke ho sebetsa ka letsatsi leo, mme re leboha haholo tsela eo o sebeletsang ka yona. Haeba e khutlisetswa, re tla o tsebisa. Re tla bonana haufinyane! 🙏",
    "Hi {name}, good news – the {service} on {date} is back on! You’re on the roster again for what you were asked to do. Thank you for serving! 🙏": "Dumela {name}, litaba tse molemo – {service} ka {date} e khutlile! O boetse o lenaneng bakeng sa seo o ileng wa kopuwa ho se etsa. Kea leboha ka ho sebeletsa! 🙏",
    "Which term": "Kotara efe",
    "Term {n} {year}": "Kotara {n} {year}",
    "Which services": "Ditshebeletso dife",
    "There are no services between these dates.": "Ha ho ditshebeletso pakeng tsa matsatsi ana.",
    "{n} page": "Leqephe le {n}",
    "{n} pages": "Maqephe a {n}",
    "Nobody is on the roster for these services yet.": "Ha ho motho lenaneng la ditshebeletso tsena hajwale.",
    "page {n} of {total}": "leqephe {n} ho {total}",
    "Printed {date}": "E hatisitswe ka {date}",
    "Show the {service} again": "Bontsha {service} hape",
    "Hidden for now:": "Ho patilwe hajwale:",
    "Show all": "Bontsha tsohle",
    "Names are now listed from A to Z in Rosters (teams and serving groups), Groups, the Librarians, the keepers and Privacy – tap a name to open the person’s page.": "Mabitso joale a thathamisitsoe ho tloha ho A ho isa ho Z ho Lenane la tshebeletso (dihlopha le dihlopha tsa tshebeletso), Dihlopha, Bahlokomedi ba laeborari, bahlokomedi le Lekunutu – tobetsa lebitso ho bula leqephe la motho.",
    "Rosters: six services side by side with a slider to move across, an eye to hide a service for now, and departments can be put in order or joined together (Teams → ↑ ↓ and ⋯).": "Lenane: ditshebeletso tse tshelela pela tse ding ka sesutumetsi sa ho tsamaya, leihlo la ho pata tshebeletso hajwale, mme mafapha a ka behwa ka tatellano kapa a kopanngwa (Dihlopha → ↑ ↓ le ⋯).",
    "Slide across to see more services": "Sutumetsa ka lehlakoreng ho bona ditshebeletso tse ding",
    "Move {team} up": "Isa {team} hodimo",
    "Move {team} down": "Isa {team} tlase",
    "Move up": "Isa hodimo",
    "Move down": "Isa tlase",
    "Join with another team…": "Kopanya le sehlopha se seng…",
    "Join with another team": "Kopanya le sehlopha se seng",
    "Delete team": "Hlakola sehlopha",
    "More for {team}": "Tse ding bakeng sa {team}",
    "Joining the teams…": "Ho kopanngwa dihlopha…",
    "{from} is now part of {to}": "{from} jwale ke karolo ya {to}",
    "Join {team} to": "Kopanya {team} le",
    "Its positions, the people on them and their turns on the roster move across. A position with the same name is joined to the one already there, so nobody is listed twice. Then {team} is removed.": "Maemo a sona, batho ba ho ona le makgetlo a bona lenaneng di fetisetswa. Boemo bo nang le lebitso le tshwanang bo kopanngwa le bo seng bo le teng, hore ho se be motho ya ngolwang habedi. Ebe {team} e a tloswa.",
    "Join them": "Di kopanye",
    "Earlier": "Pele",
    "Later services": "Ditshebeletso tse latelang",
    "Later": "Hamorao",
    "Fill the gaps for me": "Ntlatsetse dikgeo",
    "{n} suggestion": "Tlhahiso e {n}",
    "{n} suggestions": "Ditlhahiso tse {n}",
    "shown with a dashed border. Families and friends are kept together, people who are away are skipped, and turns are shared fairly.": "di bontshwa ka moedi wa matheba. Malapa le metswalle di bolokwa mmoho, ba siyo ba a tlolwa, mme dinako di arolwa ka toka.",
    "Hover or tap a suggestion to see why.": "Supa kapa o ame tlhahiso ho bona lebaka.",
    "{n} slot still can’t be filled": "Sekgeo se {n} ha se eso tlatswe",
    "{n} slots still can’t be filled": "Dikgeo tse {n} ha di eso tlatswe",
    "see below.": "bona ka tlase.",
    "Keep these and ask people": "Boloka tsena mme o botse batho",
    "Discard": "Lahla",
    "Please check": "Ka kopo hlahloba",
    "Waiting for a reply": "Ho emetswe karabo",
    "Suggestion": "Tlhahiso",
    "Gap": "Sekgeo",
    "Position": "Boemo",
    "Not at {time}": "Eseng ka {time}",
    "Add someone": "Eketsa motho",
    "Why some slots are still empty": "Lebaka leo dikgeo tse ding di ntseng di se na letho",
    "{n} more needed": "Ho sa hlokahala ba {n}",
    "Add more people to the team, or ask someone directly with “+ Add someone”.": "Eketsa batho ba bang sehlopheng, kapa o botse motho ka kotloloho ka “+ Eketsa motho”.",
    "Serves together with {names}.": "O sebeletsa mmoho le {names}.",
    "Kept apart from {names}.": "O arohantswe le {names}.",
    "This is a suggestion. Keep the suggestions to ask them.": "Ena ke tlhahiso. Boloka ditlhahiso ho ba botsa.",
    "Status": "Boemo",
    "Remove suggestion": "Tlosa tlhahiso",
    "No longer needed": "Ha ho sa hlokahala",
    "Sorry – you’re no longer needed for this:": "Re maswabi – ha o sa hlokahala bakeng sa sena:",
    "{name} has been told they’re no longer needed": "{name} o tsebisitswe hore ha a sa hlokahala",
    "the message to {name} was taken back": "molaetsa o yang ho {name} o hutsitswe",
    "Change person": "Fetola motho",
    "Instead of {name}. They’ll be told, and the new person is asked.": "Sebakeng sa {name}. Ba tla tsebiswa, mme motho e motjha o a kopuwa.",
    "Taken off the roster": "O tlositswe lenaneng",
    "Changed to {name} – waiting for their reply": "Ho fetotswe ho {name} – ho emetswe karabo ya hae",
    "Rosters: tap a name and choose Change person to swap it in one go – the first person is told, and a message they haven’t opened is taken back.": "Lenane la tshebeletso: tobetsa lebitso mme o kgethe Fetola motho ho le fetola hang – motho wa pele o a tsebiswa, mme molaetsa oo a so o bulang o a hutswa.",
    "Rosters now show only the departments and positions needed at the services you’re looking at.": "Lenane la tshebeletso jwale le bontsha feela mafapha le maemo a hlokahalang ditshebeletsong tseo o di shebileng.",
    "{old} becomes {new}; its people and turns stay.": "{old} e fetoha {new}; batho ba yona le makgetlo a bona a sala.",
    "Nothing is removed.": "Ha ho letho le tloswang.",
    "Rosters → Teams now offers a Verger, Ushers and Recorded Music, and Collection Servers and Communion Servers as two separate positions – tap Add them.": "Lenane → Dihlopha jwale le fana ka Mohlokomedi wa kereke, Ba amohelang baeti le Mmino o rekotilweng, le Ba bokellang kabelo le Ba thusang Selalelong e le maemo a mabedi a arohaneng – tobetsa Di eketse.",
    "{name} has applied to become a Church Partner.": "{name} o kentse kopo ya ho ba Molekane wa Kereke.",
    "Open the applications": "Bula dikopo",
    "One fewer for {position}": "E le nngwe e fokotseng bakeng sa {position}",
    "One more for {position}": "E le nngwe e eketsehileng bakeng sa {position}",
    "When someone applies to become a Church Partner, Administrators and Pastors now also get a message in Messages.": "Ha motho a etsa kopo ya ho ba Molekane wa Kereke, Batsamaisi le Baruti jwale ba fumana le molaetsa ho Melaetsa.",
    "Services are now shown in time order (8am, 10am, 5pm) and in their own colours on the roster, My serving and Settings.": "Ditshebeletso jwale di bontshwa ka tatellano ya nako (8 hoseng, 10 hoseng, 5 mantsiboya) le ka mebala ya tsona lenaneng, ho Tshebeletso ya ka le ho Disetting.",
    "Rosters → Teams: use − and + to choose how many people a position needs at each service, for example 2 on the sound desk.": "Lenane → Dihlopha: sebedisa − le + ho kgetha hore boemo bo hloka batho ba bakae tshebeletsong ka nngwe, mohlala 2 deskeng ya modumo.",
    "Go to a date": "Eya letsatsing",
