    "Who is responsible for {name}, who gives consent, who hears from the church, and who may collect {name}.": "Ke mang ya nang le boikarabelo ho {name}, ke mang ya fanang ka tumello, ke mang ya utlwang ho tswa kerekeng, le ke mang ya ka nkang {name}.",
