    "Only Administrators, Pastors and Children’s ministry see this. Viewing a collection restriction is logged.": "Ke Batsamaisi, Baruti le Tshebeletso ya bana feela ba bonang sena. Ho sheba thibelo ya ho nka ngwana ho a ngolwa.",
