    "Relationship to {name}": "Kamano le {name}",
    "A parent or legal guardian ({law}). Not step-parents, grandparents or collectors unless they are legal guardians.": "Motswadi kapa mohlokomedi wa molao ({law}). Eseng batswadi ba bobedi, nkgono le ntatemoholo kapa banki ba bana ntle le haeba e le bahlokomedi ba molao.",
    "Gets messages from the church about {name}.": "O fumana melaetsa ho tswa kerekeng mabapi le {name}.",
    "May collect {name}": "A ka nka {name}",
    "Can sign {name} out of children’s church.": "A ka ntsha {name} kerekeng ya bana.",
    "Parent or guardian": "Motswadi kapa mohlokomedi",
    "Not allowed to collect {name}": "Ha a dumellwe ho nka {name}",
    "Children’s ministry will see an alert. Keep the note short and factual.": "Tshebeletso ya bana e tla bona temoso. Ntlha e be kgutshwanyane mme e be nnete.",
    "(e.g. “Court order – call Karen”)": "(mohl. “Taelo ya lekgotla – letsetsa Karen”)",
    "Another household for {name}": "Lelapa le leng la {name}",
    "For example, the other parent’s home.": "Mohlala, hae ha motswadi e mong.",
    "Another household": "Lelapa le leng",
    "A household is the people who live together – what Elvanto calls a “family”. Each is named after its adults (e.g. “Tim & Clare Jacobs”). A child of separated parents can be in two households. Parents, guardians and who may collect a child are recorded on the child’s profile.": "Lelapa ke batho ba dulang mmoho – seo Elvanto e se bitsang “family”. Le leng le le leng le bitswa ka mabitso a batho ba lona ba baholo (mohl. “Tim & Clare Jacobs”). Ngwana wa batswadi ba arohaneng a ka ba malapeng a mabedi. Batswadi, bahlokomedi le ba ka nkang ngwana ba ngolwa profaeleng ya ngwana.",
    "New household": "Lelapa le letjha",
    "Search households": "Batla malapa",
    "Search by household or anyone in it": "Batla ka lelapa kapa motho ofe kapa ofe ho lona",
    "{n} household": "Lelapa le {n}",
    "{n} households": "Malapa a {n}",
    "No household matches. Try another name.": "Ha ho lelapa le tshwanang. Leka lebitso le leng.",
    "Own name": "Lebitso la lona",
    "Named after its adults": "Le bitswa ka mabitso a batho ba lona ba baholo",
    "Spouses": "Banyalani",
    "Partners": "Balekane",
    "to confirm": "ho netefatsa",
    "lives in {n} households": "o dula malapeng a {n}",
    "No one in this household yet.": "Ha ho motho lelapeng lena hajwale.",
    "This is for Administrators.": "Sena ke sa Batsamaisi.",
    "Widows and widowers – and people who have died – who were probably married to someone who has died. Church & Trellis compares households, wedding dates, email addresses, phone numbers, surnames and ages. Please check each one: these are only suggestions.": "Bahlolohadi – le batho ba hlokahetseng – bao mohlomong ba neng ba nyalane le motho ya hlokahetseng. Church & Trellis e bapisa malapa, matsatsi a lenyalo, diaterese tsa imeile, dinomoro tsa mohala, difane le dilemo. Ka kopo hlahloba e mong le e mong: ena ke ditlhahiso feela.",
    "No suggestions. Everyone Church & Trellis could match has been checked.": "Ha ho ditlhahiso. Bohle bao Church & Trellis e neng e ka ba tshwantsha ba hlahlobilwe.",
    "Yes, they were married": "E, ba ne ba nyalane",
    "Not a couple": "Hase banyalani",
    "Open each one and use {where} to choose someone, or type the name of someone who isn’t in Church & Trellis.": "Bula e mong le e mong mme o sebedise {where} ho kgetha motho, kapa ngola lebitso la motho ya seng ho Church & Trellis.",
    "Edit details → Late spouse": "Lokisa dintlha → Molekane ya hlokahetseng",
    "Finding duplicates is for Administrators and Pastors.": "Ho fumana ba ngodisitsweng habedi ke ha Batsamaisi le Baruti.",
    "People who may have been entered twice. Church & Trellis compares names (including short forms like Doug and Douglas, “known as”, typing slips, swapped and maiden names), email, mobile, birthday and Elvanto ID. Families sharing an email or phone are not counted as duplicates.": "Batho bao mohlomong ba kentsweng habedi. Church & Trellis e bapisa mabitso (ho kenyeletsa mabitso a makgutshwane a jwalo ka Doug le Douglas, “o tsebahala ka”, diphoso tsa ho ngola, mabitso a fapantsweng le difane tsa pele), imeile, mohala, letsatsi la tswalo le ID ya Elvanto. Malapa a arolelanang imeile kapa mohala ha a balwe jwalo ka a ngodisitsweng habedi.",
    "Same person: fix…": "Motho a le mong: lokisa…",
    "keeps one record, fills in what it’s missing from the other and moves consents, guardians and serving across.": "e boloka rekoto e le nngwe, e tlatsa se haellang ho tswa ho e nngwe mme e fetisetsa ditumello, bahlokomedi le tshebeletso.",
    "No duplicates found.": "Ha ho ba ngodisitsweng habedi ba fumanweng.",
    "Not the same person": "Hase motho a le mong",
    "Fix a duplicate": "Lokisa rekoto e ngodisitsweng habedi",
    "Keep one record. The other is kept for the records but taken out of lists and searches.": "Boloka rekoto e le nngwe. E nngwe e bolokwa bakeng sa direkoto empa e ntshwa manane le diphuputsong.",
    "Which record should stay?": "Ke rekoto efe e lokelang ho sala?",
    "After fixing:": "Ka mora ho lokisa:",
    "Filled in from the other record:": "Ho tladitswe ho tswa rekotong e nngwe:",
    "Different on the other record, not copied:": "Ho fapana rekotong e nngwe, ha ho kopitswa:",
    "Moved across:": "Ho fetisitswe:",
    "Pastoral notes stay with the old record (only Pastors can read them).": "Dintlha tsa boruti di sala le rekoto ya kgale (ke Baruti feela ba ka di balang).",
    "Children’s medical notes stay with the old record – ask Children’s ministry to check them.": "Dintlha tsa bongaka tsa bana di sala le rekoto ya kgale – kopa Tshebeletso ya bana ho di hlahloba.",
    "No address": "Ha ho aterese",
    "Spouses with different addresses": "Banyalani ba nang le diaterese tse fapaneng",
    "Married couples normally share one home address. Choose which address is right, or say they live apart (for example one is in a care home). Nothing changes until you choose.": "Banyalani ba nyetsaneng ka tlwaelo ba arolelana aterese e le nngwe ya hae. Kgetha hore na ke efe aterese e nepahetseng, kapa o re ba dula ba arohane (ka mohlala e mong o ntlong ya basadi kapa banna ba tsofetseng). Ha ho letho le fetohang ho fihlela o kgetha.",
    "Use {name}’s address for both": "Sebedisa aterese ya {name} bakeng sa bobedi",
    "They live apart": "Ba dula ba arohane",
    "Saved: {a} and {b} now share one address": "Ho bolokilwe: {a} le {b} jwale ba arolelana aterese e le nngwe",
    "Got it – their addresses won’t be compared": "Ho lokile – diaterese tsa bona di ke ke tsa bapiswa",
    "Change {name}’s address too?": "Fetola le aterese ya {name}?",
    "Married couples normally share one home address.": "Banyalani ba nyetsaneng ka tlwaelo ba arolelana aterese e le nngwe ya hae.",
