    "Works the same days as their category": "O sebetsa matsatsi a tshwanang le a sehlopha sa hae",
    "Consent for {name}": "Tumello ya {name}",
    "No parent or guardian who can give consent is recorded for {name}. Under {law} a parent or legal guardian gives consent for a child.": "Ha ho motswadi kapa mohlokomedi ya ka fanang ka tumello ya ngodisitsweng bakeng sa {name}. Tlasa {law} motswadi kapa mohlokomedi wa molao o fana ka tumello bakeng sa ngwana.",
    "Add them under {section} on the profile of {name}, then record consent.": "Ba eketse tlasa {section} profaeleng ya {name}, ebe o ngola tumello.",
    "Tick what they agree to. Unticking withdraws consent from today.": "Tshwaya seo ba se dumelang. Ho tlosa letshwao ho hula tumello ho qala kajeno.",
    "How it was given": "Ka moo e fanweng ka teng",
    "A new consent record for each person, dated today, with how it was given (POPIA). Children are left out: a parent or guardian answers for them on the child’s page.": "Rekoto e ntjha ya tumello ya motho ka mong, ka letsatsi la kajeno le kamoo e fanweng ka teng (POPIA). Bana ha ba kenyelletswe: motswadi kapa mohlokomedi o ba arabela leqepheng la ngwana.",
    "Choose how it was given.": "Kgetha kamoo e fanweng ka teng.",
