    "Care for the family of {name} (died {date})": "Hlokomela lelapa la {name} (o hlokahetse {date})",
    "Finish recording the death of {name}: rosters and sign-in": "Qetella ho ngola lefu la {name}: manane le ho kena",
    "Children are now linked to the adults in their household – please confirm them (see Home)": "Bana jwale ba hokahantswe le batho ba baholo lelapeng la bona – ka kopo ba netefatse (bona Lehae)",
    "Change {n} selected…": "Fetola ba {n} ba kgethilweng…",
    "Change selected…": "Fetola ba kgethilweng…",
    "This looks like someone already in Church & Trellis. Open them instead, or tick “I’ve checked: this is a different person”.": "Enwa o bonahala e le motho ya seng a le ho Church & Trellis. Mo bule ho ena le moo, kapa tshwaya “Ke hlahlobile: enwa ke motho e mong”.",
    "This looks like someone already in Church & Trellis, so it can’t be saved. Open them instead, or ask an Administrator.": "Enwa o bonahala e le motho ya seng a le ho Church & Trellis, ka hona a ke ke a bolokwa. Mo bule ho ena le moo, kapa botsa Motsamaisi.",
    "The wedding anniversary can’t be in the future.": "Sehopotso sa lenyalo se ke ke sa ba nakong e tlang.",
    "Please choose the date they died.": "Ka kopo kgetha letsatsi leo ba hlokahetseng ka lona.",
    "The partnership can’t be updated before the date they were accepted.": "Tshebedisano e ke ke ya ntjhafatswa pele ho letsatsi leo ba amohetsweng ka lona.",
    "Please choose a marital status (or “Not known”).": "Ka kopo kgetha boemo ba lenyalo (kapa “Ha ho tsejwe”).",
    "Type the name of their late spouse, or choose “Nobody recorded”.": "Ngola lebitso la molekane wa bona ya hlokahetseng, kapa kgetha “Ha ho ya ngodisitsweng”.",
    "For staff, choose their staff category and the date they started working at the church.": "Bakeng sa basebetsi, kgetha sehlopha sa bona sa basebetsi le letsatsi leo ba qadileng ho sebetsa kerekeng.",
    "Tick the days they work, or “Same as their category”.": "Tshwaya matsatsi ao ba sebetsang, kapa “Ho tshwana le sehlopha sa bona”.",
    "To give someone access to Church & Trellis, add their email address – that’s how they sign in.": "Ho fa motho phihlello ya Church & Trellis, eketsa imeile ya hae – ke kamoo a kenang ka teng.",
    "At most 4 people can share one email address to sign in. Give this person an email address of their own.": "Batho ba 4 feela ba ka arolelana aterese e le nngwe ya imeile ho kena. Fa motho enwa aterese ya hae ya imeile.",
    "{names} also signs in with this email address. Only an Administrator can give access on an email address shared with a Pastor or Administrator.": "{names} le yena o kena ka aterese ena ya imeile. Ke Motsamaisi feela ya ka fanang ka phihlello atereseng e arolelanwang le Moruti kapa Motsamaisi.",
    "{names} also signs in with this email address: after signing in, they choose who is using Church & Trellis.": "{names} le yena o kena ka aterese ena ya imeile: kamora ho kena, ba kgetha hore ke mang ya sebedisang Church & Trellis.",
    "Children must be in a household, so the church knows who they live with.": "Bana ba tlameha ho ba lelapeng, hore kereke e tsebe hore ba dula le mang.",
    "Added – now record their consent": "O eketsitswe – jwale ngola tumello ya bona",
    "Record the death of {name}": "Ngola lefu la {name}",
    "They stay on the church records, but come off rosters, teams, the directory and messages, and can no longer sign in.": "Ba sala direkotong tsa kereke, empa ba tloswa manane, dihlopheng, bukaneng ya mabitso le melaetseng, mme ha ba sa kgona ho kena.",
