    "Nothing you do is saved while you’re viewing. Pastoral and medical notes stay hidden – only Pastors and Children’s ministry may see those.": "Ha ho letho le bolokwang ha o ntse o sheba. Dintlha tsa boruti le tsa bongaka di dula di patilwe – ke Baruti le Bosebeletsi ba bana feela ba ka di bonang.",
