    "Add {n} away dates": "Kenya matsatsi a {n} a ho ba siyo",
    "Add this": "Kenya sena",
    "The name in Elvanto matches more than one person in Church & Trellis, or no one exactly.": "Lebitso le ho Elvanto le tshwana le motho ya fetang a le mong ho Church & Trellis, kapa ha le tshwane hantle le motho.",
