    "Import from Elvanto": "Kenya ho tswa Elvanto",
    "Bring your people and households (Elvanto’s “families”) across from Elvanto. Nothing is changed in Elvanto.": "Tlisa batho ba hao le malapa (“malapa” a Elvanto) ho tswa Elvanto. Ha ho letho le fetolwang ho Elvanto.",
    "Imported.": "Ho kentswe.",
    "{a} added, {u} updated, {f} households created.": "{a} ba kentswe, {u} ba ntjhafaditswe, malapa a {f} a thehilwe.",
    "{n} volunteering positions.": "Maemo a {n} a boithaopo.",
    "{n} “would like to receive” choices.": "Dikgetho tse {n} tsa “a ka rata ho amohela”.",
    "Positions Church & Trellis doesn’t have (left out): {list}.": "Maemo ao Church & Trellis e se nang ona (a tlohetswe): {list}.",
