    "Use the sheet’s settings: kinds of leave, categories and allowances, school terms, public holidays and cover rules": "Sebedisa disetting tsa sheet: mefuta ya phomolo, mafapha le ditokelo, dikotara tsa sekolo, matsatsi a phomolo a setjhaba le melao ya ho emela",
