    "{n} of them can’t sign in to Church & Trellis yet – reach them by email, WhatsApp or SMS as before.": "Ba {n} ho bona ha ba so kgone ho kena ho Church & Trellis – ba fihlele ka imeile, WhatsApp kapa SMS jwalo ka pele.",
    "Only Administrators, Pastors, carers and group leaders can send messages.": "Ke Batsamaisi, Baruti, bahlokomedi le baetapele ba dihlopha feela ba ka romelang melaetsa.",
