    "Please don’t put private or medical details in a message to a group.": "Ka kopo o se ke wa kenya dintlha tsa lekunutu kapa tsa bophelo molaetseng o yang sehlopheng.",
    "Every message sent in Church & Trellis, newest first. You can delete any of them.": "Molaetsa o mong le o mong o rometsweng ho Church & Trellis, o mocha pele. O ka hlakola ofe kapa ofe.",
