    "Delete the message": "Hlakola molaetsa",
    "Only Administrators and Pastors can set up message groups.": "Ke Batsamaisi le Baruti feela ba ka thehang dihlopha tsa melaetsa.",
    "Groups you can send messages to, besides Care Groups, the staff and Church Partners – for example Worship team leaders or the Alpha team. Leaders can send messages to their own group.": "Dihlopha tseo o ka di romelang melaetsa, ntle le dihlopha tsa tlhokomelo, basebetsi le Balekane ba Kereke – mohlala baetapele ba sehlopha sa borapedi kapa sehlopha sa Alpha. Baetapele ba ka romela melaetsa sehlopheng sa bona.",
