    "Writing a message is easier: tap the box at the top to choose who it’s for from clear cards and lists, each showing how many people it reaches.": "Ho ngola molaetsa ho bonolo jwale: tobetsa lebokose le hodimo ho kgetha hore ke wa mang, dikareteng le mananeng a hlakileng a bontshang hore e nngwe le e nngwe e fihla ho batho ba bakae.",
