    "Your question and a few help pages are sent to Google’s Gemini AI to write the answer. No church records are sent – please don’t type private matters.": "Potso ya hao le maqephe a mmalwa a thuso di romelwa ho Gemini AI ya Google hore e ngole karabo. Ha ho direkoto tsa kereke tse romelwang – ka kopo o se ke wa ngola dintho tsa lekunutu.",
