    "Not sure how to do something? Open Help, type or say your question, and get an answer written for you.": "Ha o tseba hore o etsa ntho e itseng jwang? Bula Thuso, ngola kapa o bue potso ya hao, mme o fumane karabo e ngotsweng bakeng sa hao.",
